//! Vendored JPEG files for `clazel-jpeg` (phase-6.md item 6.5): libjpeg-turbo's
//! `testimages/*.jpg` with their reference output, and the generated corpus
//! of `scripts/jpeg-reference.py`.
//!
//! The files are binary, so there is nothing to translate: like the fonts'
//! and Wuffs' GIF converters, this checks that each file is the one its
//! `SOURCE.md` names (a `` - `X`: sha256 `...` `` line), that a `.jpg` starts
//! with the SOI marker, and writes a table that embeds each with
//! `include_bytes!`. No JPEG marker is parsed here: that is the crate's job.

use std::fmt::Write as _;
use std::path::Path;

use sha2::{Digest, Sha256};

use super::fonts::listed_hash;
use super::hash::to_hex;

/// `tests/data/libjpeg-turbo-testimages/`.
pub const FILES_TESTIMAGES: &[&str] = &[
    "monkey12.jpg",
    "testimgari.jpg",
    "testimgint.jpg",
    "testimgint.ref",
    "testorig.jpg",
    "testorig.ref",
];

/// `tests/data/jpeg-corpus/`.
pub const FILES_CORPUS: &[&str] = &["corpus.pack"];

/// The files of the suite in `dir`, by its name.
fn files_of(name: &str) -> Result<&'static [&'static str], String> {
    match name {
        "libjpeg-turbo-testimages" => Ok(FILES_TESTIMAGES),
        "jpeg-corpus" => Ok(FILES_CORPUS),
        _ => Err(format!("no JPEG list for suite {name:?}")),
    }
}

/// Check the suite in `dir` and write its table.
pub fn convert(dir: &Path) -> Result<String, String> {
    let name = dir
        .file_name()
        .and_then(|n| n.to_str())
        .ok_or_else(|| format!("{}: no directory name", dir.display()))?;
    let files = files_of(name)?;
    let source =
        std::fs::read_to_string(dir.join("SOURCE.md")).map_err(|e| format!("SOURCE.md: {e}"))?;
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// Generated by `cargo xtask testdata` from `tests/data/{name}/` \
         (xtask/src/testdata/jpeg.rs). Do not edit.\n\
         \n\
         /// One vendored file, checked against `SOURCE.md` when generated.\n\
         pub struct Case {{\n    \
             /// The file's name in `tests/data/{name}/`.\n    \
             pub file: &'static str,\n    \
             /// Its SHA-256, as `SOURCE.md` lists it.\n    \
             pub sha256: &'static str,\n    \
             /// Its bytes.\n    \
             pub bytes: &'static [u8],\n\
         }}\n\
         \n\
         /// Every file of the suite.\n\
         pub const FILES: &[Case] = &["
    );
    for file in files {
        let bytes = std::fs::read(dir.join(file)).map_err(|e| format!("{file}: {e}"))?;
        let hash = to_hex(&Sha256::digest(&bytes));
        let listed = listed_hash(&source, file)?;
        if hash != listed {
            return Err(format!(
                "{file}: SHA-256 {hash} differs from SOURCE.md's {listed}"
            ));
        }
        if file.ends_with(".jpg") && !bytes.starts_with(&[0xFF, 0xD8]) {
            return Err(format!("{file}: does not start with the SOI marker"));
        }
        let _ = writeln!(
            out,
            "    Case {{\n        \
                 file: {file:?},\n        \
                 sha256: {hash:?},\n        \
                 bytes: include_bytes!(\"../data/{name}/{file}\"),\n    \
             }},"
        );
    }
    out.push_str("];\n");
    Ok(out)
}
